const LANES = ['code-reviewer', 'spec-reviewer', 'doc-updater'];
const DIGEST = /^[0-9a-f]{64}$/;
const ID = /^[A-Za-z0-9_-]{1,128}$/;
const NAME = /^[A-Za-z0-9][A-Za-z0-9_.-]{0,127}$/;
const PACKET = /^prepared-review-packet-[A-Za-z0-9_-]{1,128}$/;
const MAX = 64 * 1024;

async function digest(bytes) {
  return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256', bytes)))
    .map(byte => byte.toString(16).padStart(2, '0')).join('');
}
async function call(parent, path, body) {
  const response = await parent.fetch(new Request(`https://operator.internal${path}`, { method: 'POST',
    headers: { 'content-type': 'application/json' }, body: JSON.stringify(body) }));
  if (response.status !== 200 || response.headers.get('content-type')?.split(';')[0].trim() !== 'application/json') throw Error('Parent capability failed');
  const bytes = new Uint8Array(await response.arrayBuffer());
  if (bytes.length > MAX) throw Error('Parent capability response exceeded bound');
  return JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(bytes));
}
function parseInput(value) {
  if (!value || typeof value !== 'object' || Array.isArray(value) || Object.keys(value).length !== 2
    || typeof value.generation !== 'number' || !Number.isSafeInteger(value.generation) || value.generation < 1
    || !value.invocation || typeof value.invocation !== 'object' || Array.isArray(value.invocation)
    || !value.invocation.input || typeof value.invocation.input !== 'object'
    || !Array.isArray(value.invocation.attachments)) return null;
  const packet = value.invocation.input.packet;
  if (!packet || typeof packet !== 'object' || Object.keys(packet).length !== 2
    || !PACKET.test(packet.reference) || !DIGEST.test(packet.digest)) return null;
  const attachment = value.invocation.attachments.find(candidate => candidate?.sha256 === packet.digest
    && candidate?.mediaType === 'application/json');
  if (!attachment || !NAME.test(attachment.name) || !ID.test(attachment.locator)
    || !Number.isSafeInteger(attachment.size) || attachment.size < 1 || attachment.size > 8 * 1024 * 1024) return null;
  return { generation: value.generation, packet, attachment };
}
function taskText(packetDigest, path) {
  return `Run the approved remote Review parent on ${path}. Packet digest: ${packetDigest}. `
    + 'Use only approved child resources for code-reviewer, spec-reviewer and doc-updater. '
    + 'Write each bounded lane report to reports/<lane>.json. Do not publish, load candidate resources or claim sync/cleanup.';
}
function decode(value) {
  if (typeof value !== 'string' || value.length > 128 * 1024 || !/^[A-Za-z0-9+/]*={0,2}$/.test(value)) throw Error('Invalid storage bytes');
  return Uint8Array.from(atob(value), character => character.charCodeAt(0));
}
async function stop(parent) {
  try { return (await call(parent, '/v1/session/stop', { schemaVersion: 1 })).status === 'stopped' ? 'stopped' : 'unknown'; }
  catch { return 'unknown'; }
}

/** Package-owned Review drive over generation-bound generic parent operations. */
export async function driveReview(input, parent) {
  const parsed = parseInput(input);
  if (!parsed || !parent?.fetch) return { schemaVersion: 1, status: 'failed', checkpoint: null,
    result: { code: 'CONDUCTOR_INPUT_INVALID' } };
  const operationId = `review-generation-${parsed.generation}`;
  try {
    const session = await call(parent, '/v1/session/ensure', { schemaVersion: 1 });
    if (['reserved', 'configuring', 'configured', 'starting'].includes(session.status)) {
      return { schemaVersion: 1, status: 'waiting', checkpoint: { stage: 'session' } };
    }
    if (session.status !== 'ready') throw Error('Session unavailable');
    const restored = await call(parent, '/v1/storage/restore', { schemaVersion: 1,
      attachment: { locator: parsed.attachment.locator, sha256: parsed.attachment.sha256, size: parsed.attachment.size } });
    if (restored.status !== 'restored' || typeof restored.path !== 'string') throw Error('Restore failed');
    const pi = await call(parent, '/v1/pi/ensure', { schemaVersion: 1 });
    if (pi.ready !== true || !ID.test(pi.conversationId)) throw Error('Pi unavailable');
    const text = taskText(parsed.packet.digest, restored.path);
    const task = await call(parent, '/v1/pi/tasks', { schemaVersion: 1, taskId: operationId,
      digest: await digest(new TextEncoder().encode(JSON.stringify({ mode: 'prompt', text }))), mode: 'prompt', text });
    if (task.taskId !== operationId || !['accepted', 'queued', 'running', 'completed'].includes(task.status)) throw Error('Task unavailable');
    if (task.status !== 'completed') return { schemaVersion: 1, status: 'waiting', checkpoint: { stage: 'pi' } };

    const sealed = await call(parent, '/v1/sync/seal', { schemaVersion: 1, operationId,
      paths: LANES.map(lane => `reports/${lane}.json`) });
    if (sealed.status !== 'sealed' || !DIGEST.test(sealed.manifestDigest) || typeof sealed.prefix !== 'string'
      || !sealed.prefix.endsWith('/') || typeof sealed.filePrefix !== 'string' || !sealed.filePrefix.endsWith('/')) throw Error('Sync unavailable');
    const manifestValue = await call(parent, '/v1/storage/read', { schemaVersion: 1,
      key: `${sealed.prefix}manifest.json`, maxBytes: MAX });
    const manifestBytes = decode(manifestValue.bytes);
    if (await digest(manifestBytes) !== sealed.manifestDigest) throw Error('Manifest mismatch');
    const manifest = JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(manifestBytes));
    if (manifest.operationId !== operationId || !Array.isArray(manifest.files)) throw Error('Manifest scope mismatch');
    const reports = [];
    for (const lane of LANES) {
      const file = manifest.files.find(candidate => candidate.path === `reports/${lane}.json`);
      if (!file || !DIGEST.test(file.sha256) || !Number.isInteger(file.size) || file.size < 1 || file.size > MAX) throw Error('Missing report');
      const stored = await call(parent, '/v1/storage/read', { schemaVersion: 1,
        key: `${sealed.filePrefix}${file.path}`, maxBytes: file.size });
      const bytes = decode(stored.bytes);
      if (bytes.length !== file.size || await digest(bytes) !== file.sha256) throw Error('Report mismatch');
      const report = JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(bytes));
      if (report.schemaVersion !== 1 || report.lane !== lane || report.packetDigest !== parsed.packet.digest
        || report.generation !== parsed.generation || report.complete !== true || !Array.isArray(report.omissions)
        || report.omissions.length !== 0 || !Array.isArray(report.findings)) throw Error('Invalid report');
      reports.push(report);
    }
    const cleanup = await stop(parent);
    return { schemaVersion: 1, status: cleanup === 'stopped' ? 'completed' : 'failed', checkpoint: null,
      result: { operationId, manifestDigest: sealed.manifestDigest, cleanup, reports } };
  } catch {
    const cleanup = await stop(parent);
    return { schemaVersion: 1, status: 'failed', checkpoint: null,
      result: { code: 'CONDUCTOR_REVIEW_FAILED', cleanup } };
  }
}
